mapper.select:
SELECT vrt.review_type AS reviewType, vrt.category_code AS categoryCode, vrt.category_name AS categoryName, vrt.guide_text AS guideText, vrt.example_text AS exampleText, vrt.prompt_template AS promptTemplate, vrt.template_version AS templateVersion, vrt.sort_order AS sortOrder FROM vitamate_review_template vrt WHERE vrt.enabled = TRUE AND vrt.review_type = #{reviewType} AND vrt.category_code IN
#{categoryCode}
ORDER BY vrt.sort_order ASC, vrt.category_code ASC
